// Command genkeysyms writes format/xkb/keysyms_table.go, the keysym names of the XKB reader and writer and the
// characters they stand for, from the X11 keysym header keysymdef.h of xorgproto
// (https://gitlab.freedesktop.org/xorg/proto/xorgproto, include/X11/keysymdef.h, under The Open Group's and
// Digital's permission notices, NOTICE). Run it from the repository root:
//
//	go run ./tools/genkeysyms -h /path/to/keysymdef.h -version xorgproto-2026.1
//
// The header itself is not part of the repository; the generated file records its SHA-256. What the generator
// takes from each "#define XK_<name> <value> <comment>" line follows the header's own explanation of its comments:
// "U+XXXX" a character the keysym stands for, "<U+XXXX>" a more specific keysym of a character another keysym
// already stands for (keypad keys), "(U+XXXX)" a legacy keysym whose character is not one to one (deprecated),
// a comment starting with "deprecated" a deprecated name, "non-deprecated alias" a name kept, and any later name
// of a value already named without "deprecated" an implicitly deprecated alias.
package main

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"flag"
	"fmt"
	"go/format"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

func main() { os.Exit(run(os.Args[1:], os.Stderr)) }

func run(args []string, stderr io.Writer) int {
	fs := flag.NewFlagSet("genkeysyms", flag.ContinueOnError)
	fs.SetOutput(stderr)
	hdr := fs.String("h", "", "keysymdef.h")
	version := fs.String("version", "", "the release the header comes from, for example xorgproto-2026.1")
	out := fs.String("o", filepath.Join("format", "xkb", "keysyms_table.go"), "output file")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if *hdr == "" || *version == "" {
		fmt.Fprintln(stderr, "genkeysyms: -h and -version are required")
		return 2
	}
	data, err := os.ReadFile(*hdr)
	if err != nil {
		fmt.Fprintln(stderr, "genkeysyms:", err)
		return 1
	}
	src, err := generate(data, *version)
	if err != nil {
		fmt.Fprintln(stderr, "genkeysyms:", err)
		return 1
	}
	if err := os.WriteFile(*out, src, 0o644); err != nil {
		fmt.Fprintln(stderr, "genkeysyms:", err)
		return 1
	}
	return 0
}

var (
	defineRE = regexp.MustCompile(`^#define XK_([A-Za-z0-9_]+)\s+0x([0-9a-fA-F]+)\s*(.*)$`)
	charRE   = regexp.MustCompile(`^([<(]?)U\+([0-9A-Fa-f]{4,6})\b`)
)

// Map kinds of the generated table (format/xkb).
const (
	mapNone     = 0
	mapExact    = 1 // U+XXXX
	mapSpecific = 2 // <U+XXXX>
	mapLegacy   = 3 // (U+XXXX)
)

type entry struct {
	name       string
	value      uint32
	r          rune
	kind       int
	deprecated bool
}

func generate(data []byte, version string) ([]byte, error) {
	var entries []entry
	named := map[uint32]bool{} // a value that has a name not explicitly deprecated
	sc := bufio.NewScanner(bytes.NewReader(data))
	for sc.Scan() {
		m := defineRE.FindStringSubmatch(strings.TrimSpace(sc.Text()))
		if m == nil {
			continue
		}
		v, err := strconv.ParseUint(m[2], 16, 32)
		if err != nil {
			return nil, fmt.Errorf("XK_%s: %v", m[1], err)
		}
		c := strings.TrimSpace(m[3])
		c = strings.TrimPrefix(c, "/*")
		c = strings.TrimSuffix(c, "*/")
		c = strings.TrimPrefix(c, "//")
		c = strings.TrimSpace(c)
		e := entry{name: m[1], value: uint32(v)}
		if cm := charRE.FindStringSubmatch(c); cm != nil {
			cp, _ := strconv.ParseUint(cm[2], 16, 32)
			e.r = rune(cp)
			switch cm[1] {
			case "":
				e.kind = mapExact
			case "<":
				e.kind = mapSpecific
			case "(":
				e.kind = mapLegacy
				e.deprecated = true
			}
		}
		explicit := strings.HasPrefix(c, "deprecated")
		keep := strings.HasPrefix(c, "non-deprecated")
		if explicit {
			e.deprecated = true
		} else if !keep && named[e.value] {
			e.deprecated = true
		}
		if !explicit {
			named[e.value] = true
		}
		entries = append(entries, e)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	if len(entries) < 1000 {
		return nil, fmt.Errorf("only %d keysyms: not a keysymdef.h", len(entries))
	}
	sum := sha256.Sum256(data)
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by tools/genkeysyms from keysymdef.h of %s (SHA-256 %x). DO NOT EDIT.\n\n", version, sum)
	b.WriteString("package xkb\n\n")
	fmt.Fprintf(&b, "// KeysymSource is the release of keysymdef.h the table comes from.\nconst KeysymSource = %q\n\n", version)
	b.WriteString("// keysymTable holds every keysym name of keysymdef.h in the header's order: name, value, the character it\n")
	b.WriteString("// stands for (0: none), how (mapExact, mapSpecific, mapLegacy) and whether the name is deprecated.\n")
	b.WriteString("var keysymTable = [...]keysymEntry{\n")
	for _, e := range entries {
		fmt.Fprintf(&b, "\t{%q, 0x%x, 0x%x, %d, %t},\n", e.name, e.value, e.r, e.kind, e.deprecated)
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}
